    const from = this.crIso(this.statFrom), to = this.crIso(this.statTo);
    if (!from || !to) { this.statMsg = "כתוב תאריך התחלה ותאריך סיום בפורמט יום.חודש.שנה, למשל 31.12.2026"; return null; }
    if (from > to) { this.statMsg = "'מתאריך' מאוחר מ'עד תאריך'"; return null; }
    q.set("date_from", from); q.set("date_to", to);
  } else {
    q.set("days", this.periodSel);
  }
  if (this.statProject) q.set("project", this.statProject);
  if (this.statInviter) q.set("inviter", this.statInviter);
  this.statMsg = "";
  return q.toString();
},
onPeriod() {
  if (this.periodSel !== "custom") { this.days = +this.periodSel; this.load(); return; }
